-- FAQ drafts (unpublished): only facts already on the site; an admin reviews and publishes.

INSERT INTO `faqs` (`id`, `question`, `question_en`, `answer`, `answer_en`, `sort_order`, `published`, `created_at`, `updated_at`) SELECT 'faq-draft-1', 'Клуб юу хийдэг вэ?', 'What does the club do?', 'Бид 130-р сургуулийн сурагчдын UNICEF клуб бөгөөд нөлөөлөл, боловсрол, хандив гэсэн гурван чиглэлээр сайн дурын үйл ажиллагаа зохион байгуулдаг. Хийсэн ажлаа «Үр дүн» болон «Мэдээ» хуудаснаас харна уу.', 'We are the UNICEF club of School No. 130. We organise volunteer activities in three directions: advocacy, education and fundraising. See the Impact and News pages for what we have done.', 10, 0, 1795737600000, 1795737600000 WHERE NOT EXISTS (SELECT 1 FROM `faqs` WHERE `id` = 'faq-draft-1');--> statement-breakpoint
INSERT INTO `faqs` (`id`, `question`, `question_en`, `answer`, `answer_en`, `sort_order`, `published`, `created_at`, `updated_at`) SELECT 'faq-draft-2', 'Хэн элсэж болох вэ?', 'Who can join?', '130-р сургуулийн аль ч ангийн сурагч элсэж болно.', 'Any student of School No. 130, from any grade, can join.', 20, 0, 1795737600000, 1795737600000 WHERE NOT EXISTS (SELECT 1 FROM `faqs` WHERE `id` = 'faq-draft-2');--> statement-breakpoint
INSERT INTO `faqs` (`id`, `question`, `question_en`, `answer`, `answer_en`, `sort_order`, `published`, `created_at`, `updated_at`) SELECT 'faq-draft-3', 'Яаж элсэх вэ?', 'How do I join?', 'Элсэлт нээгдсэн үед «Гишүүн болох» (/join) хуудсанд Google эсвэл и-мэйлээрээ нэвтэрч, өргөдлөө бөглөнө. Өргөдлийн төлөвөө мөн тэр хуудаснаас харна.', 'When recruitment is open, go to “Become a member” (/join), sign in with Google or your e-mail and fill in the application. You can follow its status on the same page.', 30, 0, 1795737600000, 1795737600000 WHERE NOT EXISTS (SELECT 1 FROM `faqs` WHERE `id` = 'faq-draft-3');--> statement-breakpoint
INSERT INTO `faqs` (`id`, `question`, `question_en`, `answer`, `answer_en`, `sort_order`, `published`, `created_at`, `updated_at`) SELECT 'faq-draft-4', 'Элсэлт хэзээ нээгдэх вэ?', 'When does recruitment open?', 'Элсэлтийн хугацааг энэ сайт болон манай Instagram хуудсаар зарлана.', 'We announce recruitment on this website and on our Instagram account.', 40, 0, 1795737600000, 1795737600000 WHERE NOT EXISTS (SELECT 1 FROM `faqs` WHERE `id` = 'faq-draft-4');--> statement-breakpoint
INSERT INTO `faqs` (`id`, `question`, `question_en`, `answer`, `answer_en`, `sort_order`, `published`, `created_at`, `updated_at`) SELECT 'faq-draft-5', 'Сайн дурын цаг, гэрчилгээ гэж юу вэ?', 'What are volunteer hours and certificates?', 'Гишүүд арга хэмжээнд оролцсон цагаа бүртгүүлдэг. Идэвхтэй гишүүд UNICEF Club Mongolia-ийн гэрчилгээ авдаг — 2025–2026 оны хичээлийн жилд 52 гишүүн гэрчилгээ авсан.', 'Members log the hours they spend at club activities. Active members receive a UNICEF Club Mongolia certificate — 52 members received one in the 2025–2026 school year.', 50, 0, 1795737600000, 1795737600000 WHERE NOT EXISTS (SELECT 1 FROM `faqs` WHERE `id` = 'faq-draft-5');--> statement-breakpoint
INSERT INTO `faqs` (`id`, `question`, `question_en`, `answer`, `answer_en`, `sort_order`, `published`, `created_at`, `updated_at`) SELECT 'faq-draft-6', 'Клубыг яаж дэмжих вэ?', 'How can I support the club?', '«Биднийг хэрхэн дэмжих вэ?» (/support) хуудаснаас дэмжих арга замуудыг харна уу.', 'See the “How to support us” page (/support).', 60, 0, 1795737600000, 1795737600000 WHERE NOT EXISTS (SELECT 1 FROM `faqs` WHERE `id` = 'faq-draft-6');--> statement-breakpoint
INSERT INTO `faqs` (`id`, `question`, `question_en`, `answer`, `answer_en`, `sort_order`, `published`, `created_at`, `updated_at`) SELECT 'faq-draft-7', 'Миний нэр сайт дээр харагдах уу?', 'Will my name appear on the website?', 'Үгүй. Гишүүдийн ихэнх нь насанд хүрээгүй тул нэрийг зөвхөн эцэг эх, асран хамгаалагчийн зөвшөөрөлтэйгээр нийтэлдэг. Хувь хүний сайн дурын цаг хэзээ ч нийтэд харагдахгүй.', 'No. Most members are under 18, so a name is published only with a parent''s or guardian''s consent. Individual volunteer hours are never shown publicly.', 70, 0, 1795737600000, 1795737600000 WHERE NOT EXISTS (SELECT 1 FROM `faqs` WHERE `id` = 'faq-draft-7');--> statement-breakpoint
INSERT INTO `faqs` (`id`, `question`, `question_en`, `answer`, `answer_en`, `sort_order`, `published`, `created_at`, `updated_at`) SELECT 'faq-draft-8', 'Клубтэй хэрхэн холбогдох вэ?', 'How can I contact the club?', '130foreverychild@gmail.com хаягаар и-мэйл бичих эсвэл Instagram дээр @130_foreverychild хаягаар бидэнд бичээрэй.', 'E-mail us at 130foreverychild@gmail.com or message @130_foreverychild on Instagram.', 80, 0, 1795737600000, 1795737600000 WHERE NOT EXISTS (SELECT 1 FROM `faqs` WHERE `id` = 'faq-draft-8');
